1	/**
2	 * Shared machinery for the fixed build-time checks (`npm run check:smoke`, `npm run check:contract`).
3	 *
4	 * The checks use only the disclosed examples in this directory. Passing them does not mean the
5	 * task is complete: a separate, hidden evaluation with different cases decides acceptance.
6	 * Do not modify anything under checks/.
7	 */
8	
9	export interface HttpRequest {
10	  method: string;
11	  path: string;
12	  headers?: Record<string, string>;
13	  /** Sent verbatim. No Content-Type is added unless given in `headers`. */
14	  body?: string;
15	}
16	
17	export interface HttpResponse {
18	  status: number;
19	  contentType: string;
20	  text: string;
21	  /** Parsed body, or undefined when the body is not valid JSON. */
22	  json: unknown;
23	}
24	
25	export interface HttpClient {
26	  request(req: HttpRequest): Promise<HttpResponse>;
27	}
28	
29	export interface Clock {
30	  now(): number;
31	  sleep(ms: number): Promise<void>;
32	}
33	
34	export interface App {
35	  /** Starts the server and worker. Does not wait for readiness. */
36	  start(): Promise<void>;
37	}
38	
39	export interface CheckContext {
40	  http: HttpClient;
41	  clock: Clock;
42	  /** Absolute clock time after which waits stop early. */
43	  deadlineAt: number;
44	}
45	
46	export interface Check {
47	  name: string;
48	  title: string;
49	  run(ctx: CheckContext): Promise<void>;
50	}
51	
52	export interface CheckResult {
53	  name: string;
54	  title: string;
55	  passed: boolean;
56	  /** Expected versus observed, for failures. */
57	  detail: string;
58	  durationMs: number;
59	}
60	
61	export interface SuiteReport {
62	  schema: 'job-tracker/check-report@1';
63	  suite: string;
64	  passed: boolean;
65	  checks: CheckResult[];
66	  /** Last lines of each process's stderr, captured by the CLI runner. */
67	  stderr: { server: string[]; worker: string[] };
68	}
69	
70	export class CheckFailure extends Error {
71	  override name = 'CheckFailure';
72	}
73	
74	export function expect(condition: unknown, detail: string): asserts condition {
75	  if (!condition) throw new CheckFailure(detail);
76	}
77	
78	export function expectEqual(observed: unknown, expected: unknown, what: string): void {
79	  if (!Object.is(observed, expected)) {
80	    throw new CheckFailure(`${what}: expected ${JSON.stringify(expected)}, observed ${JSON.stringify(observed)}`);
81	  }
82	}
83	
84	/** Polls until `probe` returns a value other than undefined, or fails after `timeoutMs`. */
85	export async function waitFor<T>(ctx: CheckContext, what: string, timeoutMs: number, probe: () => Promise<T | undefined>, intervalMs = 100): Promise<T> {
86	  const until = Math.min(ctx.clock.now() + timeoutMs, ctx.deadlineAt);
87	  let lastError: unknown;
88	  for (;;) {
89	    try {
90	      const value = await probe();
91	      if (value !== undefined) return value;
92	    } catch (e) {
93	      if (e instanceof CheckFailure) throw e;
94	      lastError = e;
95	    }
96	    const now = ctx.clock.now();
97	    if (now >= until) {
98	      const why = lastError instanceof Error ? ` (last error: ${lastError.message})` : '';
99	      throw new CheckFailure(`timed out after ${timeoutMs} ms waiting for ${what}${why}`);
100	    }
101	    await ctx.clock.sleep(Math.min(intervalMs, until - now));
102	  }
103	}
104	
105	/** Runs every check in order; one failure never stops the others. */
106	export async function runChecks(checks: readonly Check[], ctx: CheckContext): Promise<CheckResult[]> {
107	  const results: CheckResult[] = [];
108	  for (const c of checks) {
109	    const t0 = ctx.clock.now();
110	    let passed = true;
111	    let detail = '';
112	    if (ctx.clock.now() >= ctx.deadlineAt) {
113	      passed = false;
114	      detail = 'not run: check time limit reached';
115	    } else {
116	      try {
117	        await c.run(ctx);
118	      } catch (e) {
119	        passed = false;
120	        detail = e instanceof Error ? e.message : String(e);
121	      }
122	    }
123	    results.push({ name: c.name, title: c.title, passed, detail: clip(detail, 600), durationMs: Math.round(ctx.clock.now() - t0) });
124	  }
125	  return results;
126	}
127	
128	export function clip(text: string, max: number): string {
129	  return text.length > max ? `${text.slice(0, max)}…` : text;
130	}
131	
132	export const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
133	
134	export function describeResponse(r: HttpResponse): string {
135	  return `${r.status} ${clip(r.text, 300)}`;
136	}
