import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

/** Total processing attempts allowed for one job (the first try plus two retries). */
export const MAX_ATTEMPTS = 3;
/** The worker counts as up if its heartbeat is at most this old. */
export const HEARTBEAT_MAX_AGE_MS = 3_000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

type JobRow = {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
};

const JOB_COLUMNS = 'id, status, input, steps, fail_attempts, attempts, progress_completed, result_output, error, created_at, updated_at';

function toJob(r: JobRow): Job {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.progress_completed, total: r.steps },
    result: r.status === 'completed' && r.result_output !== null ? { output: r.result_output } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

const iso = (ms: number): string => new Date(ms).toISOString();

/** Runs `fn` inside a write transaction. BEGIN IMMEDIATE takes the write lock up front, so the server and worker never interleave. */
export function inTransaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

export function getJob(db: DatabaseSync, id: string): Job | undefined {
  const row = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`).get(id) as JobRow | undefined;
  return row ? toJob(row) : undefined;
}

/** All jobs, newest first. */
export function listJobs(db: DatabaseSync): Job[] {
  return (db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs ORDER BY seq DESC`).all() as JobRow[]).map(toJob);
}

export type CreateOutcome = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };

/** Creates a queued job, or returns the job already created under the same idempotency key. */
export function createJob(db: DatabaseSync, payload: NewJob, idempotencyKey: string | undefined, nowMs: number = Date.now()): CreateOutcome {
  return inTransaction(db, (): CreateOutcome => {
    if (idempotencyKey !== undefined) {
      const row = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE idempotency_key = ?`).get(idempotencyKey) as JobRow | undefined;
      if (row) {
        const same = row.input === payload.input && row.steps === payload.steps && row.fail_attempts === payload.failAttempts;
        return same ? { kind: 'replayed', job: toJob(row) } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const ts = iso(nowMs);
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, available_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
    ).run(id, payload.input, payload.steps, payload.failAttempts, idempotencyKey ?? null, ts, ts);
    return { kind: 'created', job: getJob(db, id)! };
  });
}

/** Takes the oldest queued job that is due, marks it running and starts a new attempt. */
export function claimNextJob(db: DatabaseSync, nowMs: number): Job | undefined {
  return inTransaction(db, (): Job | undefined => {
    const next = db
      .prepare("SELECT id FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1")
      .get(nowMs) as { id: string } | undefined;
    if (!next) return undefined;
    db.prepare("UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ?").run(iso(nowMs), next.id);
    return getJob(db, next.id);
  });
}

export function setProgress(db: DatabaseSync, id: string, completed: number, nowMs: number): void {
  db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?').run(completed, iso(nowMs), id);
}

/** Returns a job to the queue after a failed attempt, due again at `availableAtMs`. */
export function requeueJob(db: DatabaseSync, id: string, availableAtMs: number, nowMs: number): void {
  db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?, updated_at = ? WHERE id = ?").run(availableAtMs, iso(nowMs), id);
}

export function completeJob(db: DatabaseSync, id: string, output: string, nowMs: number): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, progress_completed = steps, updated_at = ? WHERE id = ?",
  ).run(output, iso(nowMs), id);
}

export function failJob(db: DatabaseSync, id: string, error: string, nowMs: number): void {
  db.prepare("UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, updated_at = ? WHERE id = ?").run(error, iso(nowMs), id);
}

/**
 * Called once when a worker starts. Jobs left `running` belonged to a worker that died, so they are
 * queued again. A job that already used its last attempt fails, since the retry limit still applies.
 */
export function recoverInterruptedJobs(db: DatabaseSync, nowMs: number): void {
  inTransaction(db, () => {
    const ts = iso(nowMs);
    db.prepare("UPDATE jobs SET status = 'failed', result_output = NULL, error = 'transient failure', updated_at = ? WHERE status = 'running' AND attempts >= ?").run(
      ts,
      MAX_ATTEMPTS,
    );
    db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = 0, updated_at = ? WHERE status = 'running'").run(ts);
  });
}

export function writeHeartbeat(db: DatabaseSync, nowMs: number): void {
  db.prepare('INSERT INTO worker_heartbeat (id, at_ms) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET at_ms = excluded.at_ms').run(nowMs);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('DELETE FROM worker_heartbeat').run();
}

export function isWorkerUp(db: DatabaseSync, nowMs: number): boolean {
  const row = db.prepare('SELECT at_ms FROM worker_heartbeat WHERE id = 1').get() as { at_ms: number } | undefined;
  return row !== undefined && nowMs - row.at_ms < HEARTBEAT_MAX_AGE_MS;
}

