    if (KEY_PATTERN.test(raw.idempotencyKey)) key = raw.idempotencyKey;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let payload: NewJob | undefined;
  if (raw.contentType === undefined || !JSON_CONTENT_TYPE.test(raw.contentType)) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (raw.body === null) {
    fields.push({ field: 'body', message: 'request body is too large' });
  } else {
    let parsed: unknown;
    let parseOk = true;
    try {
      parsed = JSON.parse(raw.body);
    } catch {
      parseOk = false;
      fields.push({ field: 'body', message: 'body is not valid JSON' });
    }
    if (parseOk) {
      if (!isObject(parsed)) fields.push({ field: 'body', message: 'body must be a JSON object' });
      else payload = validatePayload(parsed, fields);
    }
  }

  if (fields.length > 0 || payload === undefined) return { ok: false, fields };
  return { ok: true, payload, key };
}

function validatePayload(obj: Record<string, unknown>, fields: FieldError[]): NewJob | undefined {
  const before = fields.length;
  for (const name of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(name)) fields.push({ field: name, message: 'unknown field' });
  }

  let input: string | undefined;
  if (typeof obj.input !== 'string') {
    fields.push({ field: 'input', message: 'input is required and must be a string' });
  } else if (obj.input.length < 1 || obj.input.length > 1000) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
  } else if (obj.input.trim() === '') {
    fields.push({ field: 'input', message: 'input must not be only whitespace' });
  } else {
    input = obj.input;
  }

  const steps = integerField(obj, 'steps', 1, 20, 5, fields);
  const failAttempts = integerField(obj, 'failAttempts', 0, 5, 0, fields);

  if (fields.length !== before || input === undefined) return undefined;
  return { input, steps, failAttempts };
}

function integerField(obj: Record<string, unknown>, name: string, min: number, max: number, fallback: number, fields: FieldError[]): number {
  if (!Object.hasOwn(obj, name)) return fallback;
  const value = obj[name];
  if (typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max) return value;
  fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
  return fallback;
}

