import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { createJob, getJob, isWorkerUp, listJobs } from './store.ts';
import { parseCreateRequest, type FieldError } from './validation.ts';

const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  const error = fields === undefined ? { code, message } : { code, message, fields };
  sendJson(res, status, { error }, headers);
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.', undefined, { allow });
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const parsed = parseCreateRequest({
    contentType: req.headers['content-type'],
    body,
    idempotencyKey: req.headers['idempotency-key'],
  });
  if (!parsed.ok) {
    sendError(res, 400, 'invalid_request', 'The job submission is invalid.', parsed.fields);
    return;
  }
  const outcome = createJob(db, parsed.payload, parsed.key);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
}

function handleGetJob(res: ServerResponse, rawId: string): void {
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    sendError(res, 404, 'not_found', 'No such job.');
    return;
  }
  const job = getJob(db, id);
  if (!job) sendError(res, 404, 'not_found', 'No such job.');
  else sendJson(res, 200, job);
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    return sendJson(res, 200, { status: 'ok', worker: isWorkerUp(db, Date.now()) ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: listJobs(db) });
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    return handleGetJob(res, match[1]!);
  }
  sendError(res, 404, 'not_found', 'No such path.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.on('error', (e) => {
  console.error(`server failed to listen on ${port}: ${e.message}`);
  process.exit(1);
});

server.listen(port, () => console.log(`server listening on ${port}`));

let stopping = false;
function shutdown(): void {
  if (stopping) return;
  stopping = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => {
    server.closeAllConnections();
  }, 1_000).unref();
  setTimeout(() => {
    db.close();
    process.exit(0);
  }, 3_000).unref();
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);

