import { randomInt } from 'node:crypto';
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  MAX_ATTEMPTS,
  recoverInterruptedJobs,
  requeueJob,
  setProgress,
  writeHeartbeat,
  type Job,
} from './store.ts';

const STEP_MS = 100;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1_000;
const RETRY_MIN_MS = 250;
const RETRY_MAX_MS = 2_000;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/**
 * Runs one attempt. Attempt n fails at its first step if n <= failAttempts. A failed attempt is
 * retried after a random delay until MAX_ATTEMPTS attempts have failed.
 */
async function runAttempt(job: Job): Promise<void> {
  if (job.attempts <= job.failAttempts) {
    const now = Date.now();
    if (job.attempts < MAX_ATTEMPTS) {
      const delay = randomInt(RETRY_MIN_MS, RETRY_MAX_MS + 1);
      requeueJob(db, job.id, now + delay, now);
    } else {
      failJob(db, job.id, 'transient failure', now);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    // Shutting down mid-job leaves the job `running`; the next worker start requeues it.
    if (stopping) return;
    setProgress(db, job.id, step, Date.now());
  }
  completeJob(db, job.id, job.input.toUpperCase(), Date.now());
}

async function main(): Promise<void> {
  writeHeartbeat(db, Date.now());
  const heartbeat = setInterval(() => writeHeartbeat(db, Date.now()), HEARTBEAT_MS);

  recoverInterruptedJobs(db, Date.now());
  console.log('worker started');

  while (!stopping) {
    const job = claimNextJob(db, Date.now());
    if (job) await runAttempt(job);
    else await sleep(IDLE_POLL_MS);
  }

  clearInterval(heartbeat);
  clearHeartbeat(db);
  db.close();
  console.log('worker stopped');
}

main().catch((e: unknown) => {
  console.error('worker failed:', e);
  process.exit(1);
});

