import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
import { existsSync, rmSync } from 'node:fs';
const ROOT = process.argv[2];
const DB = process.argv[3];
const PORT = 3917;
const base = `http://127.0.0.1:${PORT}`;
let failures = 0;
const check = (cond, msg) => { console.log(`${cond ? 'ok  ' : 'FAIL'} ${msg}`); if (!cond) failures++; };
const env = { ...process.env, PORT: String(PORT), DATABASE_PATH: DB };
const procs = {};
function start(name) {
  procs[name] = spawn('node', ['--disable-warning=ExperimentalWarning', `${ROOT}/dist/${name}.js`], { env, stdio: ['ignore', 'pipe', 'pipe'] });
  procs[name].stderr.on('data', (d) => process.stderr.write(`[${name}] ${d}`));
}
const stop = async (name, sig = 'SIGTERM') => { const p = procs[name]; if (!p) return; const exited = new Promise((r) => p.once('exit', (c, s) => r({ c, s }))); p.kill(sig); const r = await exited; delete procs[name]; return r; };
const req = async (method, path, body, headers = {}) => {
  const r = await fetch(base + path, { method, headers: body !== undefined ? { 'content-type': 'application/json', ...headers } : headers, body: body === undefined ? undefined : (typeof body === 'string' ? body : JSON.stringify(body)) });
  const text = await r.text();
  let json; try { json = JSON.parse(text); } catch {}
  return { status: r.status, ct: r.headers.get('content-type'), json };
};
const waitFor = async (fn, ms = 15000) => { const end = Date.now() + ms; for (;;) { const v = await fn(); if (v) return v; if (Date.now() > end) return undefined; await sleep(100); } };
const jobOf = async (id) => (await req('GET', `/api/jobs/${id}`)).json;
const finished = (id, ms) => waitFor(async () => { const j = await jobOf(id); return j && ['completed', 'failed'].includes(j.status) ? j : undefined; }, ms);

rmSync(DB, { force: true }); rmSync(DB + '-wal', { force: true }); rmSync(DB + '-shm', { force: true });
// Start server first, worker later: ordering must not matter.
start('server');
await waitFor(async () => (await req('GET', '/health').catch(() => null))?.status === 200, 10000);
let h = await req('GET', '/health');
check(h.json?.worker === 'down', `health reports worker down before worker starts (${JSON.stringify(h.json)})`);
start('worker');
check((await waitFor(async () => (await req('GET', '/health')).json?.worker === 'up', 3000)) === true, 'worker up within 3 s of start');

// Validation.
const bad = [
  ['malformed json', '{"input":', [{ field: 'body' }]],
  ['array body', [1], [{ field: 'body' }]],
  ['empty input', { input: '   ' }, [{ field: 'input' }]],
  ['too long', { input: 'a'.repeat(1001) }, [{ field: 'input' }]],
  ['steps 0', { input: 'x', steps: 0 }, [{ field: 'steps' }]],
  ['steps 21', { input: 'x', steps: 21 }, [{ field: 'steps' }]],
  ['steps 2.5', { input: 'x', steps: 2.5 }, [{ field: 'steps' }]],
  ['steps string', { input: 'x', steps: '3' }, [{ field: 'steps' }]],
  ['failAttempts 6', { input: 'x', failAttempts: 6 }, [{ field: 'failAttempts' }]],
  ['unknown field', { input: 'x', colour: 1 }, [{ field: 'colour' }]],
];
for (const [name, body, expect] of bad) {
  const r = await req('POST', '/api/jobs', body);
  check(r.status === 400 && r.json?.error?.code === 'invalid_request' && expect.every((e) => r.json.error.fields.some((f) => f.field === e.field)), `reject: ${name}`);
}
let r = await req('POST', '/api/jobs', { input: 'x' }, { 'content-type': 'text/plain' });
check(r.status === 400 && r.json.error.fields[0].field === 'body', 'reject: wrong content-type');
r = await fetch(base + '/api/jobs', { method: 'POST', body: JSON.stringify({ input: 'x' }) });
check(r.status === 400, 'reject: missing content-type');
r = await req('POST', '/api/jobs', { input: 'x' }, { 'idempotency-key': 'bad key!' });
check(r.status === 400 && r.json.error.fields.some((f) => f.field === 'Idempotency-Key'), 'reject: bad idempotency key');
r = await req('POST', '/api/jobs', { input: 'x' }, { 'idempotency-key': '' });
check(r.status === 400, 'reject: empty idempotency key');
r = await req('POST', '/api/jobs', { input: 'x'.repeat(1000) });
check(r.status === 201, 'accept: 1000-char input');

// Defaults and lifecycle.
r = await req('POST', '/api/jobs', { input: 'Hello world' });
check(r.status === 201 && r.json.steps === 5 && r.json.failAttempts === 0 && r.json.progress.total === 5 && r.json.status === 'queued', 'create with defaults');
const dflt = r.json.id;
const t0 = Date.now();
let j = await waitFor(async () => { const x = await jobOf(dflt); return x.status === 'running' ? x : undefined; }, 3000);
check(!!j, `picked up within 1 s (took ${Date.now() - t0} ms)`);
const seen = new Set();
const pollEnd = Date.now() + 2000;
while (Date.now() < pollEnd) { const x = await jobOf(dflt); seen.add(x.progress.completed); await sleep(50); }
check(seen.size > 2, `progress observable mid-run (values ${[...seen].join(',')})`);
j = await finished(dflt, 5000);
check(j?.status === 'completed' && j.result.output === 'HELLO WORLD' && j.progress.completed === 5 && j.attempts === 1 && j.error === null, 'completed with output and progress 5/5');

// failAttempts 3 -> failed after 3 attempts, no result.
r = await req('POST', '/api/jobs', { input: 'doomed', steps: 1, failAttempts: 3 });
const doomed = r.json.id;
j = await finished(doomed, 15000);
check(j?.status === 'failed' && j.error === 'transient failure' && j.attempts === 3 && j.result === null, `failAttempts 3 fails after 3 attempts (${JSON.stringify(j && { s: j.status, a: j.attempts, e: j.error })})`);

// failAttempts 2 -> completes on attempt 3.
r = await req('POST', '/api/jobs', { input: 'two', steps: 2, failAttempts: 2 });
j = await finished(r.json.id, 15000);
check(j?.status === 'completed' && j.attempts === 3 && j.result.output === 'TWO', 'failAttempts 2 completes on attempt 3');

// Idempotency across restart.
const key = { 'idempotency-key': 'restart-key_1' };
const first = await req('POST', '/api/jobs', { input: 'keyed', steps: 1 }, key);
check(first.status === 201, 'keyed create 201');
const replay = await req('POST', '/api/jobs', { input: 'keyed' , steps: 1, failAttempts: 0 }, key);
check(replay.status === 200 && replay.json.id === first.json.id, 'keyed replay 200 same job (defaults normalised)');
const conflict = await req('POST', '/api/jobs', { input: 'keyed2' }, key);
check(conflict.status === 409 && conflict.json.error.code === 'idempotency_conflict', 'keyed conflict 409');

// Routing.
check((await req('GET', '/nope')).status === 404, 'unknown path 404');
r = await req('DELETE', '/api/jobs');
check(r.status === 405 && r.json.error.code === 'method_not_allowed', 'wrong method 405');
r = await req('GET', '/api/jobs/does-not-exist');
check(r.status === 404 && r.json.error.code === 'not_found', 'missing job 404');
const html = await fetch(base + '/');
check((await html.text()).includes('data-testid="job-form"'), 'GET / serves UI');

// Durability: SIGKILL both, restart, check state; leave a job running mid-way.
const longJob = await req('POST', '/api/jobs', { input: 'long running job', steps: 20 });
await waitFor(async () => (await jobOf(longJob.json.id)).status === 'running', 3000);
await sleep(400);
await stop('worker', 'SIGKILL');
await stop('server', 'SIGKILL');
check(existsSync(DB), 'database file exists after SIGKILL');
start('server');
start('worker');
await waitFor(async () => (await req('GET', '/health').catch(() => null))?.status === 200, 10000);
const before = await req('GET', '/api/jobs');
check(before.json.jobs.some((x) => x.id === first.json.id && x.status === 'completed' || x.id === first.json.id), 'jobs survive restart');
check(before.json.jobs.some((x) => x.id === doomed && x.status === 'failed'), 'failed job still failed after restart');
const after = await finished(longJob.json.id, 10000);
check(after?.status === 'completed' && after.result.output === 'LONG RUNNING JOB', 'interrupted running job is reprocessed to completion');
check((await req('GET', '/api/jobs')).json.jobs.length === before.json.jobs.length, 'no duplicate jobs after restart');
const keyed = await req('POST', '/api/jobs', { input: 'keyed', steps: 1 }, key);
check(keyed.status === 200 && keyed.json.id === first.json.id, 'idempotency key still honoured after restart');

// Worker down detection after SIGKILL.
await stop('worker', 'SIGKILL');
await sleep(3500);
h = await req('GET', '/health');
check(h.json.worker === 'down', 'worker reported down after SIGKILL');
// Clean shutdown
const sr = await stop('server'); const wr = await stop('worker');
check(sr.c === 0 && wr.c === 0, `graceful SIGTERM exit codes server=${sr.c} worker=${wr.c}`);
console.log(failures === 0 ? 'ALL PASSED' : `${failures} FAILURE(S)`);
process.exit(failures ? 1 : 0);
EOF
